# Words the diary must never contain: no guilt, loneliness or absence-shaming.
def num(value: object, default: float = 0.0) -> float:
    """A number from a frozen JSON payload; missing or malformed values read as ``default``."""
    if isinstance(value, bool):
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value)
        except ValueError:
            return default
    return default


def seq(value: object) -> tuple[object, ...]:
    """A list from a frozen JSON payload (frozen lists are tuples)."""
    return tuple(value) if isinstance(value, (list, tuple)) else ()


def mapping(value: object) -> Mapping[str, object]:
    """An object from a frozen JSON payload."""
    return value if isinstance(value, Mapping) else {}


