def thaw(value: object) -> object:
    """Turn frozen provenance payloads back into plain JSON values."""

    kind = type(value)
    if kind is str or kind is int or kind is bool or value is None:
        return value
    if kind is MappingProxyType or kind is dict:
        return {str(key): thaw(item) for key, item in value.items()}  # type: ignore[attr-defined]
    if kind is tuple or kind is list:
        return [thaw(item) for item in value]  # type: ignore[attr-defined]
    if isinstance(value, Mapping):
        return {str(key): thaw(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [thaw(item) for item in value]
    return value


def event_json(event: Event) -> dict[str, object]:
    return {
        "event_id": event.event_id,
        "kind": event.kind,
        "occurred_at": event.occurred_at.isoformat(),
        "source": {
            "kind": event.source.kind,
            "source_id": event.source.source_id,
            "reliability": event.source.reliability,
            "version": event.source.version,
        },
        "trace_id": event.trace_id,
        "payload": thaw(event.payload),
        "parent_event_ids": list(event.parent_event_ids),
    }


def canonical(event: Event) -> str:
    return json.dumps(event_json(event), sort_keys=True, separators=(",", ":"), ensure_ascii=False)


class EventLog:
    """L1: append-only events with a SHA-256 chain over their canonical form."""

    def __init__(self) -> None:
        self.events: list[Event] = []
        self.digests: list[str] = []
        self._by_id: dict[str, Event] = {}

    def append(
        self,
        kind: str,
        at: datetime,
        source: tuple[str, str, float],
        payload: Mapping[str, object],
        trace_id: str,
        parents: Sequence[str] = (),
    ) -> Event:
        seq = len(self.events) + 1
        source_kind, source_id, reliability = source
        event = Event(
            event_id=f"E{seq:06d}",
            kind=kind,
            occurred_at=at,
            observed_at=at,
            source=SourceRef(source_kind, source_id, reliability, CORE_VERSION),
            trace_id=trace_id,
            payload=payload,
            parent_event_ids=tuple(dict.fromkeys(parents)),
        )
        previous = self.digests[-1] if self.digests else "genesis"
        digest = hashlib.sha256((previous + canonical(event)).encode()).hexdigest()
        self.events.append(event)
        self.digests.append(digest)
        self._by_id[event.event_id] = event
        return event

    def get(self, event_id: str) -> Event | None:
        return self._by_id.get(event_id)

    @property
    def head(self) -> str:
        return self.digests[-1] if self.digests else "genesis"

    def verify(self) -> bool:
        previous = "genesis"
        for event, digest in zip(self.events, self.digests, strict=True):
            if hashlib.sha256((previous + canonical(event)).encode()).hexdigest() != digest:
                return False
            previous = digest
        return True


