def _touch_strength(times: Sequence[datetime], now: datetime, half_life_days: int) -> int:
    """Deterministic memory strength: each support adds, spacing adds more, time fades."""

    keep_per_day = content_keep(half_life_days)
    strength = 0
    last: datetime | None = None
    for moment in times:
        if last is not None:
            strength = decay(strength, 0, keep_per_day, (moment - last).days)
            gap_bonus = 3 if (moment - last) >= timedelta(hours=20) else 2
        else:
            gap_bonus = 3
        increment = 1200 * gap_bonus // 2
        strength += increment * (SCALE - strength) // SCALE
        last = moment
    if last is not None:
        strength = decay(strength, 0, keep_per_day, (now - last).days)
    return strength


_KEEP_CACHE: dict[int, int] = {}


def content_keep(half_life_days: int) -> int:
    """Fixed-point per-day keep factor for a half-life (computed by integer bisection)."""

    if half_life_days in _KEEP_CACHE:
        return _KEEP_CACHE[half_life_days]
    from duckmind.engines.v4_0.duckcore.fixed import power

    low, high = 0, SCALE
    while low < high:
        middle = (low + high + 1) // 2
        if power(middle, half_life_days) <= SCALE // 2:
            low = middle
        else:
            high = middle - 1
    _KEEP_CACHE[half_life_days] = low
    return low


def excluded_ids(events: Iterable[Event]) -> set[str]:
    """Event IDs removed by forget tombstones that were not undone."""

    forgets: dict[str, set[str]] = {}
    for event in events:
        if event.kind == "memory.forget":
            ids = event.payload.get("event_ids", ())
            forgets[event.event_id] = (
                {str(item) for item in ids} if isinstance(ids, tuple) else set()
            )
        elif event.kind == "memory.forget_undone":
            forgets.pop(str(event.payload.get("forget_event_id", "")), None)
    result: set[str] = set()
    for ids in forgets.values():
        result |= ids
    return result


def _local(moment: datetime) -> str:
    return moment.strftime("%m/%d %H:%M")


def _hour_bucket(moment: datetime) -> str:
    hour = moment.hour
    if 5 <= hour < 11:
        return "早上"
    if 11 <= hour < 17:
        return "下午"
    if 17 <= hour < 22:
        return "晚上"
    return "深夜"


def distill(events: Sequence[Event], now: datetime, name: str) -> Distilled:
    """Rebuild L2–L4 from L1. Pure: same events and ``now`` give the same memory."""

    excluded = excluded_ids(events)
    live = [event for event in events if event.event_id not in excluded]
    episodes = _episodes(live)
    facts = _facts(live, now, episodes)
    diary = _diary(live, name)
    return Distilled(episodes, facts, diary, excluded, len(live))


def walk_cm(events: Iterable[Event]) -> tuple[int, list[Event]]:
    """Distance the duck walked by itself, in cm, and the walks (wander) behind it.

    A walk logs its planned distance (from the measured ground speed); a fall or a hand
    that stopped it logs how much of that plan was never walked.
    """
    total = 0
    walks: list[Event] = []
    seen: set[str] = set()
    for event in events:
        if event.kind == "duck.walk":
            total += int(num(event.payload.get("cm")))
            seen.add(event.event_id)
            if event.payload.get("verb") == "wander":
                walks.append(event)
        elif event.kind in {"body.fell", "duck.posture"}:
            cut = mapping(event.payload.get("walk_cut"))
            if str(cut.get("walk", "")) in seen:  # a forgotten walk takes its cut with it
                total -= int(num(cut.get("cm_short")))
    return max(0, total), walks


def spot_area(x: float, y: float) -> str:
    """Which part of the 6 m × 6 m floor a point is in (mat = 0, 0)."""
    near_x, near_y = abs(x) >= 1.8, abs(y) >= 1.8
    if near_x and near_y:
        return "角落"
    if near_x or near_y:
        return "牆邊"
    if x * x + y * y <= 0.36:
        return "墊子旁邊"
    return "地板中間"


def spot_place(x: float, y: float) -> str:
    """The same, in the duck's words: 那個角落 / 牆邊那裡 / 墊子旁邊 / 地板中間那一塊."""
    return {"角落": "那個角落", "牆邊": "牆邊那裡", "地板中間": "地板中間那一塊"}.get(
        spot_area(x, y), spot_area(x, y)
    )


