def is_avoid_spot(event: Event) -> bool:
    return event.kind == "learning.committed" and str(
        event.payload.get("parameter", "")
    ).startswith("self.avoid_spot:")


def meters_text(cm: int) -> str:
    """0.4 公尺 / 12 公尺: one decimal below ten meters (integer math, no rounding drift)."""
    if cm >= 1000:
        return f"{cm // 100} 公尺"
    return f"{cm // 100}.{cm % 100 // 10} 公尺"


def _episodes(events: Sequence[Event]) -> list[Episode]:
    episodes: list[Episode] = []
    visit_start: Event | None = None
    visit_ids: list[str] = []
    touch_burst: list[Event] = []
    play_start: Event | None = None
    # A day with a nest (Duck Core v4): from waking by itself to falling asleep.
    day_start: Event | None = None
    day_ids: list[str] = []
    day_outings = 0
    play_ids: list[str] = []
    # An outing: from standing up by itself to sitting down again (or a fall, or power-off).
    outing: list[Event] = []

    def close_outing() -> None:
        walks = [
            event
            for event in outing
            if event.kind == "duck.walk" and event.payload.get("verb") == "wander"
        ]
        if walks:
            cm, _ = walk_cm(outing)
            episodes.append(
                Episode(
                    f"O-{outing[0].event_id}",
                    "walk",
                    outing[0].occurred_at,
                    outing[-1].occurred_at,
                    [event.event_id for event in outing],
                    f"自己走走 {len(walks)} 次，約 {meters_text(cm)}",
                    min(SCALE, 3500 + 700 * len(walks)),
                )
            )
        outing.clear()

    def close_touch() -> None:
        if len(touch_burst) >= 1:
            start, end = touch_burst[0].occurred_at, touch_burst[-1].occurred_at
            count = len(touch_burst)
            episodes.append(
                Episode(
                    f"T-{touch_burst[0].event_id}",
                    "touch",
                    start,
                    end,
                    [event.event_id for event in touch_burst],
                    f"被摸了 {count} 次頭（{_hour_bucket(start)}）",
                    min(SCALE, 2500 + 1500 * count),
                )
            )
        touch_burst.clear()

    for event in events:
        if event.kind == "power.on":
            visit_start = event
            visit_ids = [event.event_id]
            continue
        if visit_start is not None:
            visit_ids.append(event.event_id)
        if event.kind == "duck.posture":
            posture = event.payload.get("posture")
            if posture == "stand" and event.payload.get("from") in {"sit", "fallen"}:
                close_outing()
                outing.append(event)
            elif outing:
                outing.append(event)
                if posture != "stand":
                    close_outing()
        elif event.kind == "duck.walk" and outing:
            outing.append(event)
        elif event.kind == "body.fell" and outing:
            outing.append(event)
            close_outing()
        if event.kind == "sense.touch":
            if touch_burst and event.occurred_at - touch_burst[-1].occurred_at > timedelta(
                minutes=3
            ):
                close_touch()
            touch_burst.append(event)
        if event.kind == "pad.play_start":
            play_start = event
            play_ids = [event.event_id]
        elif play_start is not None and event.kind in {"body.play", "pad.play_end"}:
            play_ids.append(event.event_id)
            if event.kind == "pad.play_end":
                minutes = int(num(event.payload.get("minutes")))
                meters = int(num(event.payload.get("meters")))
                episodes.append(
                    Episode(
                        f"P-{play_start.event_id}",
                        "play",
                        play_start.occurred_at,
                        event.occurred_at,
                        list(play_ids),
                        f"手把陪玩 {minutes} 分鐘，走了約 {meters} 公尺",
                        min(SCALE, 4000 + 200 * minutes),
                    )
                )
                play_start = None
        if event.kind == "duck.greeting" and event.payload.get("kind") in {"reunion", "owner"}:
            episodes.append(
                Episode(
                    f"R-{event.event_id}",
                    "reunion",
                    event.occurred_at,
                    event.occurred_at,
                    [event.event_id, *event.parent_event_ids],
                    str(event.payload.get("text", "打招呼")),
                    6000,
                )
            )
        if event.kind == "duck.self_wake":
            day_start, day_ids, day_outings = event, [event.event_id], 0
        elif day_start is not None:
            if event.kind == "duck.excursion" and event.payload.get("phase") == "start":
                day_outings += 1
                day_ids.append(event.event_id)
            elif event.kind in {"sense.touch", "duck.greeting", "nest.docked", "duck.predict"}:
                day_ids.append(event.event_id)
            if event.kind == "memory.consolidated" and event.payload.get("segment") == "day":
                minute = int(num(day_start.payload.get("at_min")))
                episodes.append(
                    Episode(
                        f"D-{day_start.event_id}",
                        "day",
                        day_start.occurred_at,
                        event.occurred_at,
                        [*day_ids[:60], event.event_id],
                        f"{minute // 60:02d}:{minute % 60:02d} 起床的一天，出門走了 {day_outings} 趟",
                        min(SCALE, 3000 + 40 * day_outings),
                    )
                )
                day_start, day_ids = None, []
        if event.kind == "power.off" and visit_start is not None:
            close_touch()
            close_outing()
            minutes = int(num(event.payload.get("awake_min")))
            episodes.append(
                Episode(
                    f"V-{visit_start.event_id}",
                    "visit",
                    visit_start.occurred_at,
                    event.occurred_at,
                    list(visit_ids),
                    f"{_hour_bucket(visit_start.occurred_at)}的拜訪，醒著 {minutes} 分鐘",
                    3000,
                )
            )
            visit_start = None
            visit_ids = []
    close_touch()
    close_outing()
    return episodes


def _add_fact(
    facts: dict[str, Fact],
    fact_id: str,
    category: str,
    subject: str,
    predicate: str,
    text: str,
    evidence: Sequence[Event],
    now: datetime,
    *,
    half_life_days: int = 30,
    floor: int = 0,
    value: object = None,
) -> None:
    if not evidence:
        return
    times = [event.occurred_at for event in evidence]
    strength = max(floor, _touch_strength(times, now, half_life_days))
    facts[fact_id] = Fact(
        fact_id=fact_id,
        category=category,
        subject=subject,
        predicate=predicate,
        text=text,
        evidence=[event.event_id for event in evidence],
        first_at=times[0],
        last_at=times[-1],
        strength=strength,
        half_life_days=half_life_days,
        floor=floor,
        value=value,
    )


def _facts(events: Sequence[Event], now: datetime, episodes: Sequence[Episode]) -> dict[str, Fact]:
    facts: dict[str, Fact] = {}
    by_kind: dict[str, list[Event]] = {}
    for event in events:
        by_kind.setdefault(event.kind, []).append(event)

    touches = by_kind.get("sense.touch", [])
    crown = [event for event in touches if event.payload.get("where") == "crown"]
    if crown:
        _add_fact(
            facts,
            "F-touch-crown",
            "like",
            "家人",
            "摸我的頭頂",
            "家裡有人常常搔我的頭頂，我很喜歡。",
            crown,
            now,
        )
    pickups = by_kind.get("sense.pickup", [])
    if len(pickups) >= 5:
        _add_fact(facts, "F-pickup", "like", "我", "喜歡被抱", "我喜歡被抱起來了。", pickups, now)
    # Only calls heard with the TV off: with it on, the duck cannot tell who said its name.
    called = [
        event for event in by_kind.get("sense.name_heard", []) if not event.payload.get("tv_on")
    ]
    if len(called) >= 3:
        _add_fact(
            facts,
            "F-name",
            "bond",
            "家人",
            "叫我的名字",
            "家裡有人會叫我的名字，我聽到會抬頭回應。",
            called,
            now,
            half_life_days=60,
        )

    owner_events = [event for event in events if event.kind in {"owner.hello", "owner.good"}]
    bond_updates = [
        event
        for event in by_kind.get("learning.committed", [])
        if event.payload.get("parameter") == "owner.bond"
    ]
    if owner_events:
        bond = bond_updates[-1].payload.get("after") if bond_updates else None
        _add_fact(
            facts,
            "F-owner",
            "bond",
            "主人",
            "對我很好",
            "主人會跟我打招呼、誇我；我聽到主人的招呼會特別開心。",
            owner_events,
            now,
            half_life_days=60,
            value=bond,
        )

    # Favourite verb / phrase from committed household preferences (latest value wins).
    latest_pref: dict[str, tuple[float, Event]] = {}
    for event in by_kind.get("learning.committed", []):
        parameter = str(event.payload.get("parameter", ""))
        if parameter.startswith("household."):
            after = event.payload.get("after")
            if isinstance(after, (int, float)):
                latest_pref[parameter] = (float(after), event)
    verb_prefs = {
        key: item for key, item in latest_pref.items() if key.startswith("household.verb:")
    }
    if verb_prefs:
        best_key = max(sorted(verb_prefs), key=lambda key: verb_prefs[key][0])
        best_value, best_event = verb_prefs[best_key]
        verb_id = best_key.split(":", 1)[1]
        verb = content.VERB_BY_ID.get(verb_id)
        if verb is not None and best_value > 0.5:
            support = [item[1] for key, item in verb_prefs.items() if key == best_key]
            evidence = [
                event
                for event in by_kind.get("learning.committed", [])
                if event.payload.get("parameter") == best_key
            ] or support
            _add_fact(
                facts,
                "F-fav-verb",
                "like",
                "我",
                "最喜歡的動作",
                f"我最喜歡做「{verb.zh}」，你們常誇我。",
                evidence,
                now,
                value=verb_id,
            )

    promoted = by_kind.get("voice.promoted", [])
    if promoted:
        counts: dict[str, int] = {}
        for event in promoted:
            code = str(event.payload.get("code", ""))
            counts[code] = counts.get(code, 0) + 1
        undone = {
            str(event.payload.get("code", ""))
            for event in by_kind.get("voice.promotion_undone", [])
        }
        ranked = sorted(
            (code for code in counts if code not in undone), key=lambda code: (-counts[code], code)
        )
        if ranked:
            favourite = ranked[0]
            text = next(
                (
                    str(event.payload.get("text", favourite))
                    for event in promoted
                    if event.payload.get("code") == favourite
                ),
                favourite,
            )
            _add_fact(
                facts,
                "F-fav-phrase",
                "song",
                "我們家",
                "最喜歡的片語",
                f"我們家最喜歡的片語是「{text}」。",
                [event for event in promoted if event.payload.get("code") == favourite],
                now,
                half_life_days=90,
                value=favourite,
            )
    songs = by_kind.get("voice.song", [])
    if songs:
        latest = songs[-1]
        _add_fact(
            facts,
            "F-song",
            "song",
            "我們家",
            "我們家的歌",
            f"我們家的歌（第 {latest.payload.get('version')} 版）：{latest.payload.get('text')}",
            songs,
            now,
            half_life_days=365,
            floor=6000,
            value=latest.payload.get("phrases"),
        )

    plays = by_kind.get("pad.play_end", [])
    if plays:
        meters = sum(int(num(event.payload.get("meters"))) for event in plays)
        _add_fact(
            facts,
            "F-play",
            "like",
            "家人",
            "用手把帶我玩",
            f"你們常用手把帶我玩，我們一共走了約 {meters} 公尺。",
            plays,
            now,
            value=meters,
        )

    walked, walks = walk_cm(events)
    if len(walks) >= 5:
        _add_fact(
            facts,
            "F-explore",
            "like",
            "我",
            "自己到處走走",
            f"我喜歡自己到處走走，到現在自己走了大約 {meters_text(walked)}。",
            walks,
            now,
            value=walked,
        )
    falls = by_kind.get("body.fell", [])
    if falls:
        times = "一次" if len(falls) == 1 else f" {len(falls)} 次"
        outcomes = [
            str(event.payload.get("outcome"))
            for event in by_kind.get("body.righting", [])
            if event.payload.get("outcome")
        ]
        easy = outcomes.count("easy")
        got_up = f"其中 {easy} 次自己一下就翻回來了；" if easy else ""
        _add_fact(
            facts,
            "F-fell",
            "habit",
            "我",
            "跌倒過",
            f"我走路時跌倒過{times}，{got_up}跌倒沒關係，我還是喜歡到處走走。",
            falls,
            now,
            half_life_days=14,
            value=len(falls),
        )
    # A spot it fell at, and could hardly get up from, three times or more: it keeps away.
    for event in [event for event in by_kind.get("learning.committed", []) if is_avoid_spot(event)]:
        spot = mapping(event.payload.get("spot"))
        place = spot_place(num(spot.get("x")), num(spot.get("y")))
        zone = str(event.payload.get("parameter")).split(":", 1)[1]
        cited = {str(item) for item in seq(event.payload.get("evidence_event_ids"))}
        support = [item for item in events if item.event_id in cited]
        _add_fact(
            facts,
            f"F-avoid-{zone}",
            "habit",
            "我",
            "不適合走的地方",
            f"{place}我跌倒好幾次、很難自己翻回來，不太敢走過去。",
            [*support, event],
            now,
            half_life_days=60,
            value={"x": num(spot.get("x")), "y": num(spot.get("y")), "r": num(spot.get("r"))},
        )

    visits = [episode for episode in episodes if episode.kind == "visit"]
    if len(visits) >= 3:
        buckets: dict[str, list[Episode]] = {}
        for episode in visits:
            buckets.setdefault(_hour_bucket(episode.start), []).append(episode)
        top = max(sorted(buckets), key=lambda key: len(buckets[key]))
        evidence_ids = [episode.event_ids[0] for episode in buckets[top]]
        support = [event for event in events if event.event_id in set(evidence_ids)]
        _add_fact(
            facts,
            "F-time",
            "pattern",
            "我們家",
            "常見的時段",
            f"我們常在{top}見面。",
            support,
            now,
            value=top,
        )

    sounds = by_kind.get("env.daily_sound", [])
    tv_days = [event for event in sounds if num(event.payload.get("tv_minutes")) > 0]
    if tv_days:
        _add_fact(
            facts,
            "F-tv",
            "pattern",
            "家裡",
            "常有電視聲",
            "家裡常常有電視的聲音（我只記得每天大概多少，不記得內容）。",
            tv_days,
            now,
        )

    for event in by_kind.get("growth.branch", []) + by_kind.get("growth.branch_changed", []):
        branch_id = str(event.payload.get("branch") or event.payload.get("to") or "")
        branch = content.BRANCH_BY_ID.get(branch_id)
        if branch is not None:
            _add_fact(
                facts,
                "F-trait",
                "trait",
                "我",
                "個性",
                f"我是{branch.zh}：{branch.style}。",
                [event],
                now,
                half_life_days=365,
                floor=8000,
                value=branch_id,
            )
    for event in by_kind.get("growth.adult", []):
        _add_fact(
            facts,
            "F-adult",
            "trait",
            "我",
            "成鴨",
            f"我長成「{event.payload.get('name')}」了。",
            [event],
            now,
            half_life_days=365,
            floor=8000,
        )
    for event in by_kind.get("growth.quirk", []):
        quirk = str(event.payload.get("quirk", "quirk"))
        text = str(event.payload.get("text", ""))
        _add_fact(
            facts,
            f"F-quirk-{quirk}",
            "quirk",
            "我",
            "怪癖：" + text.removeprefix("我").removeprefix("發現我")[:9],
            text,
            [event],
            now,
            half_life_days=365,
            floor=5000,
        )
    for event in by_kind.get("growth.milestone", []):
        milestone = str(event.payload.get("milestone", ""))
        _add_fact(
            facts,
            f"F-ms-{milestone}",
            "milestone",
            "我",
            str(event.payload.get("title", "")),
            str(event.payload.get("text", "")),
            [event],
            now,
            half_life_days=365,
            floor=4000,
        )
    for event in by_kind.get("rare.event", []):
        rare_id = str(event.payload.get("id", ""))
        if f"F-rare-{rare_id}" not in facts:
            same = [item for item in by_kind["rare.event"] if item.payload.get("id") == rare_id]
            _add_fact(
                facts,
                f"F-rare-{rare_id}",
                "rare",
                "我",
                str(event.payload.get("zh")),
                f"我有過「{event.payload.get('zh')}」的時候。",
                same,
                now,
                half_life_days=120,
            )
    # Its clever and goofy moments: an album (like the rare one), and its running gags.
    moments_by_id: dict[str, list[Event]] = {}
    for event in by_kind.get("duck.moment", []):
        moments_by_id.setdefault(str(event.payload.get("id", "")), []).append(event)
    for moment_id, same in sorted(moments_by_id.items()):
        label = "機智" if same[0].payload.get("kind") == "clever" else "呆萌"
        zh = str(same[0].payload.get("zh", ""))
        _add_fact(
            facts,
            f"F-moment-{moment_id}",
            "rare",
            "我",
            f"{label}：{zh[:10]}",
            f"我的{label}時刻：{zh}",
            same,
            now,
            half_life_days=120,
            value=len(same),
        )
    for event in by_kind.get("moment.gag_promoted", []):
        moment_id = str(event.payload.get("id", ""))
        _add_fact(
            facts,
            f"F-gag-{moment_id}",
            "habit",
            "我們家",
            "招牌梗",
            f"我們家的招牌梗：{event.payload.get('zh')}（你們好幾天都笑了）",
            [event, *moments_by_id.get(moment_id, [])[-12:]],
            now,
            half_life_days=180,
            floor=5000,
        )
    for index, event in enumerate(by_kind.get("keepsake", [])):
        alone = event.payload.get("kind") == "self_walk"
        _add_fact(
            facts,
            f"F-keep-{index}",
            "keepsake",
            "我" if alone else "我們",
            f"{'自己' if alone else '一起'}走了 {event.payload.get('meters')} 公尺",
            str(event.payload.get("text", "")),
            [event],
            now,
            half_life_days=365,
            floor=6000,
        )
    tamed = [
        event
        for event in by_kind.get("growth.milestone", [])
        if event.payload.get("milestone") == "tamed_hand"
    ]
    if tamed:
        slow = [
            event
            for event in by_kind.get("sense.hand_near", [])
            if event.payload.get("speed") == "slow"
        ]
        _add_fact(
            facts,
            "F-tame",
            "habit",
            "我",
            "不怕慢慢靠近的手",
            "以前手靠近我會縮一下；現在我會靠過去。",
            slow or tamed,
            now,
            half_life_days=120,
        )
    return facts


def _diary(events: Sequence[Event], name: str) -> list[DiaryDay]:
    days: dict[str, DiaryDay] = {}
    current_gd = 0
    touches_by_day: dict[str, list[str]] = {}
    names_by_day: dict[str, list[str]] = {}
    walks_by_day: dict[str, list[Event]] = {}
    # Greetings it stood up for: the reflex decision names the greeting as its parent.
    stood_for = {
        parent
        for event in events
        if event.kind == "duck.decision"
        and event.payload.get("rule") == "reflex-v1"
        and event.payload.get("trigger") == "greet_stand"
        and event.payload.get("verb") == "stand_up"
        for parent in event.parent_event_ids
    }
    seen_moments: set[str] = set()
    moments_by_day: dict[str, list[Event]] = {}
    reacted: set[str] = set()
    for event in events:
        if event.kind == "moment.reaction" and event.parent_event_ids:
            reacted.add(event.parent_event_ids[0])
    for event in events:
        date = event.occurred_at.strftime("%Y-%m-%d")
        if event.kind == "growth.gd":
            current_gd = int(num(event.payload.get("gd"), current_gd)) or current_gd
            continue
        day = days.setdefault(date, DiaryDay(date=date, gd=current_gd, lines=[]))
        line: DiaryLine | None = None
        if event.kind == "duck.moment":
            moments_by_day.setdefault(date, []).append(event)
            moment_id = str(event.payload.get("id", ""))
            if moment_id not in seen_moments:
                seen_moments.add(moment_id)
                line = DiaryLine(f"第一次：{event.payload.get('zh')}", [event.event_id], "positive")
                day.positive += 1
        elif event.kind == "duck.day_form" and event.payload.get("form") != "ordinary":
            line = DiaryLine(str(event.payload.get("zh", "")), [event.event_id], "neutral")
        elif event.kind == "moment.gag_promoted":
            line = DiaryLine(
                f"「{event.payload.get('zh')}」變成我們家的招牌梗了！", [event.event_id], "positive"
            )
            day.positive += 1
        elif event.kind == "growth.milestone":
            line = DiaryLine(str(event.payload.get("text", "")), [event.event_id], "positive")
            day.positive += 2
        elif event.kind == "voice.promoted":
            line = DiaryLine(
                f"「{event.payload.get('text')}」正式成為我們家的片語了。",
                [event.event_id],
                "positive",
            )
            day.positive += 1
        elif event.kind == "voice.liked" and num(event.payload.get("days")) == 1:
            line = DiaryLine(
                f"你們好像喜歡我說「{event.payload.get('text')}」，我會再試試看。",
                [event.event_id],
                "positive",
            )
        elif event.kind == "rare.event":
            line = DiaryLine(f"今天我{event.payload.get('zh')}！", [event.event_id], "positive")
        elif event.kind == "duck.greeting" and event.payload.get("kind") == "owner":
            stood = "站起來" if event.event_id in stood_for else ""
            line = DiaryLine(
                f"主人跟我打招呼，我{stood}用我們的招呼回答了。", [event.event_id], "positive"
            )
            day.positive += 1
        elif event.kind in {"duck.walk", "body.fell", "duck.posture"}:
            walks_by_day.setdefault(date, []).append(event)
            if event.kind == "body.fell":
                line = DiaryLine("今天走路時跌了一跤，沒關係。", [event.event_id], "gentle")
        elif event.kind == "body.righting" and event.payload.get("outcome"):
            line = DiaryLine(
                RIGHTING_ZH.get(str(event.payload.get("outcome")), ""), [event.event_id], "gentle"
            )
        elif is_avoid_spot(event):
            spot = mapping(event.payload.get("spot"))
            place = spot_place(num(spot.get("x")), num(spot.get("y")))
            line = DiaryLine(
                f"{place}我跌倒好幾次，不太敢走過去了，以後走路會繞開那裡。",
                [event.event_id],
                "gentle",
            )
        elif event.kind == "pad.play_end":
            line = DiaryLine(
                f"你們用手把帶我玩了 {event.payload.get('minutes')} 分鐘，玩完好累好開心。",
                [event.event_id],
                "positive",
            )
            day.positive += 1
        elif event.kind == "duck.reaction" and event.payload.get("to") == "overload":
            line = DiaryLine(
                "有一下子太多了，我縮了一下，休息後就好了。", [event.event_id], "gentle"
            )
            day.negative += 1
        elif event.kind == "duck.stop":
            day.negative += 1
        elif event.kind == "sense.touch":
            touches_by_day.setdefault(date, []).append(event.event_id)
        elif event.kind == "sense.name_heard" and not event.payload.get("tv_on"):
            names_by_day.setdefault(date, []).append(event.event_id)
        elif event.kind == "keepsake":
            line = DiaryLine(str(event.payload.get("text", "")), [event.event_id], "positive")
        elif event.kind == "voice.song":
            line = DiaryLine(
                f"我的歌有了新版本：{event.payload.get('text')}", [event.event_id], "positive"
            )
        elif event.kind == "memory.forget":
            line = DiaryLine("主人請我忘掉一段記憶，我已經忘了。", [event.event_id], "neutral")
        elif event.kind == "duck.self_wake":
            minute = int(num(event.payload.get("at_min")))
            line = DiaryLine(
                f"今天我 {minute // 60}:{minute % 60:02d} 就自己起床了。",
                [event.event_id],
                "positive",
            )
        elif event.kind == "duck.predict_outcome" and event.payload.get("hit"):
            line = DiaryLine(
                "你們回家前我就醒來在窩上等你們了，猜對了！", [event.event_id], "positive"
            )
            day.positive += 1
        elif event.kind == "duck.nap_start" and event.payload.get("reason") == "away_rest":
            if not any("在窩裡睡了一覺" in item.text for item in day.lines):
                line = DiaryLine("大家出門的時候，我在窩裡睡了一覺。", [event.event_id], "neutral")
        elif event.kind == "duck.greeting" and event.payload.get("kind") == "reunion":
            if int(num(event.payload.get("tier"))) >= 1:
                line = DiaryLine("你們回來了！我好開心地打了招呼。", [event.event_id], "positive")
                day.positive += 1
        if line is not None and line.text:
            day.lines.append(line)
    for date, walked in walks_by_day.items():
        cm, walks = walk_cm(walked)
        if cm > 0 and walks:
            day = days[date]
            day.positive += 1
            day.lines.insert(
                0,
                DiaryLine(
                    f"今天我自己走了約 {meters_text(cm)}。",
                    [event.event_id for event in walks][:12],
                    "positive",
                ),
            )
    # Each day's pick of its moments (the one the family reacted to, clever first), and on
    # each Sunday the week's cleverest and goofiest (the ones the family reacted to most).
    week: dict[str, list[Event]] = {"clever": [], "goofy": []}
    for date in sorted(moments_by_day):
        items = moments_by_day[date]
        ranked = sorted(
            items,
            key=lambda e: (
                e.event_id not in reacted,
                e.payload.get("kind") != "clever",
                e.occurred_at,
            ),
        )
        pick = ranked[0]
        day = days[date]
        if not any(pick.event_id in line.cites for line in day.lines):
            day.lines.append(
                DiaryLine(f"今天的精選：{pick.payload.get('zh')}", [pick.event_id], "positive")
            )
        for event in items:
            week[str(event.payload.get("kind"))].append(event)
        if datetime.fromisoformat(date).weekday() == 6:
            for kind, label in (("clever", "本週機智精選"), ("goofy", "本週呆萌精選")):
                if week[kind]:
                    best = max(
                        week[kind],
                        key=lambda e: (e.event_id in reacted, e.occurred_at),
                    )
                    day.lines.append(
                        DiaryLine(f"{label}：{best.payload.get('zh')}", [best.event_id], "positive")
                    )
            week = {"clever": [], "goofy": []}
    for date, ids in names_by_day.items():
        day = days[date]
        day.positive += 1
        day.lines.insert(
            0, DiaryLine(f"今天有人叫了我的名字 {len(ids)} 次。", ids[:12], "positive")
        )
    for date, ids in touches_by_day.items():
        day = days[date]
        day.positive += min(3, len(ids))
        day.lines.insert(0, DiaryLine(f"今天有人摸了我的頭 {len(ids)} 次。", ids[:12], "positive"))
    for day in days.values():
        for line in day.lines:
            for banned in DIARY_BANNED:
                if banned in line.text:
                    raise AssertionError(f"diary linter rejected: {banned}")
    return [day for date, day in sorted(days.items()) if day.lines]
